// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAlerts Danh sách cảnh báo dịch
	// (GET /alerts)
	ListAlerts(ctx context.Context, request ListAlertsRequestObject) (ListAlertsResponseObject, error)
	// ConfirmAlert Xác nhận cảnh báo và tự động mở hồ sơ xử lý
	// (POST /alerts/{alert_id}/confirm)
	ConfirmAlert(ctx context.Context, request ConfirmAlertRequestObject) (ConfirmAlertResponseObject, error)
	// Login Đăng nhập
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Đăng xuất (thu hồi refresh token trong cookie)
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshToken Cấp access token mới bằng refresh token trong cookie (xoay vòng)
	// (POST /auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// ListCases Danh sách hồ sơ xử lý dịch
	// (GET /cases)
	ListCases(ctx context.Context, request ListCasesRequestObject) (ListCasesResponseObject, error)
	// CreateCase Tạo hồ sơ xử lý dịch mới
	// (POST /cases)
	CreateCase(ctx context.Context, request CreateCaseRequestObject) (CreateCaseResponseObject, error)
	// GetCase Chi tiết hồ sơ xử lý dịch
	// (GET /cases/{case_id})
	GetCase(ctx context.Context, request GetCaseRequestObject) (GetCaseResponseObject, error)
	// CreateAllocationPlan Tạo phương án phân bổ nguồn lực cho hồ sơ
	// (POST /cases/{case_id}/allocation-plans)
	CreateAllocationPlan(ctx context.Context, request CreateAllocationPlanRequestObject) (CreateAllocationPlanResponseObject, error)
	// CreateDraft Tạo dự thảo văn bản cho hồ sơ (B2B hoặc B2G)
	// (POST /cases/{case_id}/drafts)
	CreateDraft(ctx context.Context, request CreateDraftRequestObject) (CreateDraftResponseObject, error)
	// ListDataVersions Các phiên bản dữ liệu (panel) đã công bố
	// (GET /data-versions)
	ListDataVersions(ctx context.Context, request ListDataVersionsRequestObject) (ListDataVersionsResponseObject, error)
	// GetDraft Chi tiết dự thảo văn bản
	// (GET /drafts/{draft_id})
	GetDraft(ctx context.Context, request GetDraftRequestObject) (GetDraftResponseObject, error)
	// UpdateDraft Cập nhật nội dung dự thảo (tăng version, tính lại content_hash)
	// (PATCH /drafts/{draft_id})
	UpdateDraft(ctx context.Context, request UpdateDraftRequestObject) (UpdateDraftResponseObject, error)
	// DispatchApprovedOrder Ban hành lệnh điều phối sau khi dự thảo đã được duyệt
	// (POST /drafts/{draft_id}/dispatch)
	DispatchApprovedOrder(ctx context.Context, request DispatchApprovedOrderRequestObject) (DispatchApprovedOrderResponseObject, error)
	// SubmitReview Phê duyệt / Từ chối / Yêu cầu sửa dự thảo (Áp dụng quy tắc 4 mắt)
	// (POST /drafts/{draft_id}/reviews)
	SubmitReview(ctx context.Context, request SubmitReviewRequestObject) (SubmitReviewResponseObject, error)
	// ListForecastRuns Danh sách lượt dự báo
	// (GET /forecast-runs)
	ListForecastRuns(ctx context.Context, request ListForecastRunsRequestObject) (ListForecastRunsResponseObject, error)
	// CreateForecastRun Tạo lượt dự báo (chạy nền). Vai trò tối thiểu `analyst`.
	// (POST /forecast-runs)
	CreateForecastRun(ctx context.Context, request CreateForecastRunRequestObject) (CreateForecastRunResponseObject, error)
	// GetForecastRun Chi tiết một lượt dự báo
	// (GET /forecast-runs/{run_id})
	GetForecastRun(ctx context.Context, request GetForecastRunRequestObject) (GetForecastRunResponseObject, error)
	// GetProvinceGeometry Ranh giới 34 tỉnh (GeoJSON, có phiên bản — bất biến theo `version`)
	// (GET /geo/provinces)
	GetProvinceGeometry(ctx context.Context, request GetProvinceGeometryRequestObject) (GetProvinceGeometryResponseObject, error)
	// GetJob Trạng thái job chạy nền (polling)
	// (GET /jobs/{job_id})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// GetMe Người dùng hiện tại
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetModelCard Model card rút gọn của phiên bản mô hình đang dùng
	// (GET /model-card)
	GetModelCard(ctx context.Context, request GetModelCardRequestObject) (GetModelCardResponseObject, error)
	// ListLimitations Danh sách giới hạn đã biết (đo được) của mô hình
	// (GET /model-card/limitations)
	ListLimitations(ctx context.Context, request ListLimitationsRequestObject) (ListLimitationsResponseObject, error)
	// ListModelVersions Các phiên bản mô hình (danh mục đóng, trả đủ — không phân trang)
	// (GET /model-versions)
	ListModelVersions(ctx context.Context, request ListModelVersionsRequestObject) (ListModelVersionsResponseObject, error)
	// ListObservations Chuỗi quan sát theo tháng của một tỉnh
	// (GET /observations)
	ListObservations(ctx context.Context, request ListObservationsRequestObject) (ListObservationsResponseObject, error)
	// ListProvinces Danh mục 34 tỉnh (danh mục đóng, trả đủ — không phân trang)
	// (GET /provinces)
	ListProvinces(ctx context.Context, request ListProvincesRequestObject) (ListProvincesResponseObject, error)
	// GetProvince Chi tiết một tỉnh
	// (GET /provinces/{province_id})
	GetProvince(ctx context.Context, request GetProvinceRequestObject) (GetProvinceResponseObject, error)
	// GetProvinceExplanation Yếu tố ảnh hưởng dự báo (SHAP) cho một tỉnh, một tầm dự báo
	// (GET /provinces/{province_id}/explanations)
	GetProvinceExplanation(ctx context.Context, request GetProvinceExplanationRequestObject) (GetProvinceExplanationResponseObject, error)
	// GetProvinceForecasts Dự báo một tỉnh cho đủ các tầm dự báo của một lượt
	// (GET /provinces/{province_id}/forecasts)
	GetProvinceForecasts(ctx context.Context, request GetProvinceForecastsRequestObject) (GetProvinceForecastsResponseObject, error)
	// GetRiskMap Bản đồ rủi ro — dự báo 34 tỉnh cho một lượt và một tầm dự báo (BFF ghép nhiều service)
	// (GET /risk-map)
	GetRiskMap(ctx context.Context, request GetRiskMapRequestObject) (GetRiskMapResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

